#[test]
fn closed_incremental_failures_eventually_trip() {
    let mut cb = CircuitBreaker::new();
    // Add failures one at a time, checking state transition
    for i in 1..=20u32 {
        cb.record_failure();
        if cb.state() == CircuitBreakerState::Open {
            // Should trip when failure rate exceeds 50%
            // All operations are failures, so it should trip after enough samples
            assert!(i >= 2, "should need at least 2 failures to calculate a rate");
            return;
        }
    }
    panic!("circuit breaker should have tripped after 20 consecutive failures");
}

